from pathlib import Path
from html import escape
R=Path(__file__).resolve().parent
SERV=[('seismic-permitting','Seismic Permitting','Land access, approvals and field coordination for geophysical programs.'),('right-of-way-acquisition','Right-of-Way Acquisition','Easements, property rights and acquisition for infrastructure corridors.'),('title-leasing','Title and Leasing','Ownership research, title curative and leasing.'),('gis','GIS Services','Mapping, spatial reconciliation and project databases.')]
def nav(p):
 return f'''<header class="nav"><a class="mark" href="{p}"><img src="{p}assets/logo.png" alt="APS Land Services"></a><button class="menu" aria-expanded="false" aria-controls="navlinks" aria-label="Open navigation">Menu +</button><nav id="navlinks" class="navlinks" aria-label="Primary"><a href="{p}services/">Services</a><a href="{p}about/">Company</a><a href="{p}safety/">Safety</a><a href="{p}landowners/">Landowners</a><a class="contactlink" href="{p}contact/">Contact APS ↗</a></nav></header>'''
def footer(p):
 return f'''<footer class="footer"><div class="shell"><div>© 2026 APS Land Services · Utah / Montana / Texas</div><div><a href="{p}services/">Services</a><a href="{p}safety/">Safety</a><a href="{p}landowners/">Landowners</a><a href="{p}privacy/">Privacy</a></div><div><a href="mailto:contact@apsland.com">contact@apsland.com</a></div></div></footer>'''
def page(path,title,desc,content):
 d=R/path;d.mkdir(parents=True,exist_ok=True);depth=len(Path(path).parts) if path else 0;p='../'*depth
 s=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{escape(title)} | APS Land Services</title><meta name="description" content="{escape(desc)}"><meta name="theme-color" content="#101b24"><link rel="icon" href="{p}favicon-32x32.png"><link rel="stylesheet" href="{p}css/site.css"></head><body><a class="skip" href="#main">Skip to content</a>{nav(p)}<main id="main">{content}</main>{footer(p)}<script src="{p}js/site.js" defer></script></body></html>'''
 (d/'index.html').write_text(s)
rows=''.join(f'<a class="service-row" href="services/{slug}/"><span class="number">0{i}</span><h3>{name}</h3><p>{description}</p><span class="arr">↗</span></a>' for i,(slug,name,description) in enumerate(SERV,1))
home=f'''<section class="hero"><div class="land" aria-hidden="true"></div><div class="shell"><div class="overline">APS / Land Services / North America</div><h1>Land.<span>Understood.</span></h1><p class="lead">Seismic permitting, right-of-way acquisition, title and leasing, and GIS services for energy and infrastructure projects.</p><div class="actions"><a class="arrowlink" href="services/">Explore our work</a><a class="arrowlink" href="contact/">Discuss an assignment</a></div><div class="scroll">SCROLL TO EXPLORE ↓</div></div></section>
<section class="chapter services"><div class="shell"><div class="chapter-head"><div class="overline eyebrow">01 / Capabilities</div><div><h2>Four disciplines.<br>One clear scope.</h2><p style="font-size:19px;line-height:1.65;max-width:620px;color:#52616a">Engage APS for a single service or for work across a project's lifecycle.</p></div></div><div class="service-list">{rows}</div></div></section>
<section class="statement"><div class="shell"><div class="overline small">02 / The work behind the work</div><p>Before a crew can move, someone has to know who owns the land, what rights are needed, and what the agreement allows.</p></div></section>
<section class="chapter"><div class="shell"><div class="chapter-head"><div class="overline eyebrow">03 / Experience</div><div><h2>Experience measured in projects, not promises.</h2></div></div><div class="facts"><p>APS reports work on hundreds of energy and infrastructure projects across 28 states, Alberta and Saskatchewan. The work includes thousands of negotiations across private, state, federal and tribal lands.</p><div class="stats"><div><span>Seismic industry experience</span><strong>Since 1980</strong></div><div><span>Reported geographic experience</span><strong>28 states</strong></div><div><span>Company locations</span><strong>UT / MT / TX</strong></div></div></div></div></section>
<section class="chapter light"><div class="shell"><div class="chapter-head"><div class="overline eyebrow">04 / Accountability</div><div><h2>The people responsible are not behind another layer.</h2></div></div><div class="editorial"><div><p>APS states that senior leadership is engaged on every project. Scope and deliverables are defined up front. Title, mapping, acquisition and field information are reconciled as work develops.</p><a class="arrowlink" href="about/">Meet APS leadership</a></div><div><p>Reporting is part of the work, not an afterthought. When ownership, access or alignments change, the record must change with them.</p></div></div><div class="portrait"><a href="about/"><img src="assets/mark.jpg" alt="Mark Fischbuch" loading="lazy"><h3>Mark Fischbuch</h3><p>President and Founder</p></a><a href="about/"><img src="assets/zane.jpg" alt="Zane Nelson" loading="lazy"><h3>Zane Nelson</h3><p>Vice President</p></a></div></div></section>
<section class="chapter"><div class="shell"><div class="chapter-head"><div class="overline eyebrow">05 / Safety and HSE</div><div><h2>Safety is documented. Expectations are explicit.</h2></div></div><div class="editorial"><p>APS operates under a Safety Program Manual and Injury and Illness Prevention Program, with daily briefings, job safety analyses and stop-work authority.</p><div><p>APS is an ISNetworld member. Details of its safety practices and contractor-management contact are available on the dedicated page.</p><a class="arrowlink" href="safety/">Safety and HSE</a></div></div></div></section>
<section class="close frame"><div class="shell"><div class="overline">An assignment starts with a conversation</div><h2>Tell us what the project needs.</h2><a class="arrowlink" href="contact/">Contact APS</a><p style="margin-top:42px"><a class="mail" href="mailto:contact@apsland.com">contact@apsland.com</a> &nbsp; · &nbsp; <a class="mail" href="tel:3039035873">303-903-5873</a></p></div></section>'''
page('','APS Land Services','Seismic permitting, right-of-way acquisition, title and leasing, and GIS services for energy and infrastructure projects.',home)
def inner(slug,title,desc,body):
 p='../'*len(Path(slug).parts)
 aside='<aside><div class="overline eyebrow">Explore APS</div>'+''.join(f'<a href="{p}services/{s}/">{n} ↗</a>' for s,n,_ in SERV)+f'<a href="{p}safety/">Safety and HSE ↗</a><a href="{p}contact/">Contact APS ↗</a></aside>'
 page(slug,title,desc,f'<section class="interior-hero"><div class="shell"><div class="overline">APS Land Services / {escape(title)}</div><h1>{escape(title)}</h1><p>{escape(desc)}</p></div></section><section class="inner-content"><div class="shell inner-grid">{aside}<article>{body}<p style="margin-top:55px"><a class="arrowlink" href="{p}contact/">Discuss this scope</a></p></article></div></section>')
inner('services','Services','Seismic permitting, right-of-way acquisition, title and leasing, and GIS.', '<h2>Engage APS where the work requires it.</h2><p>Individual assignments, related scopes and project reviews are all valid starting points.</p>'+''.join(f'<h3><a href="{slug}/">{name} ↗</a></h3><p>{desc}</p>' for slug,name,desc in SERV))
inner('services/seismic-permitting','Seismic Permitting','Land access and permitting for geophysical and complex field programs.','<h2>Access comes before acquisition.</h2><p>APS coordinates landowner contact, property conditions, permitting and field compliance for seismic programs, including 2D, 3D, 4D, microseismic and VSP work.</p><h3>What the work involves</h3><p>Ownership research, access negotiations, municipal and agency approvals, permit tracking, payments, field conditions and damage coordination.</p><h3>Where details matter</h3><p>Landowner conditions, wildlife restrictions, access routes and field requirements need to be carried from the agreement into the work itself.</p>')
inner('services/right-of-way-acquisition','Right-of-Way Acquisition','Property rights and easements for linear infrastructure.','<h2>When an alignment changes, the land work changes with it.</h2><p>Route revisions can introduce different tracts, owners, title questions and agreements. APS coordinates ownership, GIS and acquisition information as a corridor develops.</p><h3>Acquisition scope</h3><p>Permanent and temporary easements, workspace, access agreements, tract acquisition tracking, landowner negotiations and executed documentation.</p><h3>Corridor work</h3><p>Pipeline, electric transmission, utility, telecommunications and road projects.</p>')
inner('services/title-leasing','Title and Leasing','Surface and mineral ownership research, title curative and lease acquisition.','<h2>The record is rarely as simple as the map.</h2><p>Ownership may be split across surface and mineral estates, multiple generations, probate records and historical instruments. APS traces and reconciles records to support project planning, negotiation and acquisition.</p><h3>Research and coordination</h3><p>Title searches to sovereignty, surface and mineral ownership, probate and heirship, title curative coordination, and leasing.</p><p class="note">APS’s precise role in legal title opinions remains subject to company clarification. No attorney-rendered opinion service is claimed here.</p>')
inner('services/gis','GIS Services','Mapping and databases connecting ownership records with project geography.','<h2>Spatial information has to agree with the record.</h2><p>APS compiles and reconciles project mapping, legal descriptions, ownership information and acquisition status for planning and field use.</p><h3>Work product</h3><p>Project mapping, tract platting, spatial data compilation, reconciliation, database development and map exhibits.</p><p class="note">GIS mapping supports project analysis; it does not replace licensed surveying or authoritative boundary determinations.</p>')
inner('about','About APS','Established land-services experience with direct senior involvement.','<h2>Experience starts in the field.</h2><p>Mark Fischbuch began working in the seismic industry in 1980. His field experience shaped an approach to research, land access and coordination intended to reduce avoidable friction for crews and landowners.</p><div class="bio"><img src="../assets/mark.jpg" alt="Mark Fischbuch"><div><h3>Mark Fischbuch</h3><p>President and Founder. Decades of experience in seismic operations, land access and field oversight.</p></div></div><div class="bio"><img src="../assets/zane.jpg" alt="Zane Nelson"><div><h3>Zane Nelson</h3><p>Vice President. With APS since 2010, involved in financial structure, project leadership and daily operations.</p></div></div><h3>How APS engages</h3><p>Senior leadership involvement, defined deliverables, direct communication and reconciliation across land, title, mapping and field work.</p>')
inner('safety','Safety and HSE','Written safety programs, field practices and contractor management.','<h2>Written standards. Field accountability.</h2><p>APS operates under its Safety Program Manual, Injury and Illness Prevention Program and applicable client and project requirements.</p><h3>Field practices</h3><ul><li>Daily safety briefings</li><li>Job safety analyses</li><li>Stop-work authority</li><li>Compliance monitoring</li></ul><h3>Contractor management</h3><p>APS is an ISNetworld member. Membership does not imply qualification or approval by any particular operator.</p>')
inner('landowners','Landowners','If an APS representative contacted you, you can reach APS directly.','<h2>Questions about an agreement or project?</h2><p>If APS has contacted you about land access, our representatives can explain the project, who APS represents and what access is being requested.</p><p>We are happy to answer any questions you may have about an agreement or project. Call or email APS directly.</p><p><a href="tel:3039035873">303-903-5873</a><br><a href="mailto:contact@apsland.com">contact@apsland.com</a></p>')
inner('contact','Contact','Discuss a project, landowner question or contractor-management request.','<h2>Start with the scope.</h2><p>For project inquiries, it helps to share the type of work, location, current stage and approximate timeline. APS can discuss individual assignments or related scopes.</p><h3>Direct contact</h3><p><a href="tel:3039035873">303-903-5873</a><br><a href="mailto:contact@apsland.com">contact@apsland.com</a></p><h3>Landowners</h3><p>If an APS representative has contacted you, we welcome your questions. <a href="../landowners/">Landowner information ↗</a></p><h3>Procurement</h3><p>For safety documentation and contractor-management inquiries, contact APS at the details above.</p>')
inner('privacy','Privacy Policy','Publication pending approved privacy language.','<h2>Staging notice</h2><p>This test website is not a production privacy policy. Approved privacy language is required before public launch.</p>')
(R/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | APS</title><style>body{font:18px system-ui;background:#101b24;color:#eeeae0;min-height:80vh;display:grid;place-items:center}a{color:#c47b66}</style><main><h1>Page not found.</h1><p><a href="./">Return to APS Land Services ↗</a></p></main></html>')
(R/'README.md').write_text('# APS Concept 04 — Groundwork\n\nAn independent static website concept. Deploy the contents of this folder to the root of a separate GitHub Pages test repository. All pages include noindex,nofollow while testing.\n\nThis is a new visual composition, not a production release. It uses an original illustrative landform, supplied APS logo and leadership portraits, and independently condensed copy based on the provided research and Copy Master. Validate all company claims and approve editorial changes before publication.\n\nNo external fonts, images, scripts, frameworks, or trackers. The privacy page is a staging placeholder. Do not remove noindex until approved.\n')
print('Built',len(list(R.rglob('index.html'))),'pages')
